{
  "status": "requires_manufacturer_documentation",
  "summary": "The handbook only states that bolt torque values must follow the aircraft or engine manufacturer's specifications and does not provide the specific tightening torque for the high‑pressure compressor bolts of a CFM56‑7B.",
  "claims": [
    {
      "text": "Torque values for engine bolts are to be tightened to the torque recommended by the aircraft/engine manufacturer.",
      "citations": [5]
    },
    {
      "text": "Torque is defined as the product of a force and its distance from the axis, measured in pound‑inches or pound‑feet.",
      "citations": [2]
